// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;

import "./IBEP20.sol";

library Shared{
    struct advert{
        address payable owner;
        uint amount;
        address asset;
        uint balance;
        bool closed;
    }
}


contract Advert{
    
    event AdvertClosed(string advertId);
    event Deposited(string advertId,uint amount);
    event AssetTransferred(string advertId,uint amount,address buyer);
    

    mapping(string=>Shared.advert) public Adverts;

    function createAdvert (string memory _advertId,uint _amount, address _asset) external payable{
        require(_amount > 0, "initial deposit cannot be null");
        IBEP20(_asset).transferFrom(msg.sender, address(this), _amount);
        Adverts[_advertId] = Shared.advert(payable(msg.sender),_amount,_asset,_amount,false);
    }

    function deposit(string memory advertId,uint _amount) external payable{
        Shared.advert storage ad = Adverts[advertId];
        require(msg.sender == ad.owner, "unauthorized to deposit"); 
        IBEP20(ad.asset).transferFrom(msg.sender, address(this), _amount);
        Adverts[advertId].balance += _amount;
        emit Deposited(advertId,_amount);
    }

    receive() external payable{}

    function close(string memory advertId) external{
        Shared.advert storage ad = Adverts[advertId];
        require(ad.balance > 0, "insufficient balance");
        require(msg.sender == ad.owner,"unauthorized to close advert");
        IBEP20(ad.asset).transferFrom(address(this), msg.sender, ad.balance);
        Adverts[advertId].balance -= ad.balance;
        emit AdvertClosed(advertId);
    }

    function transferAsset(string memory advertId,address payable buyer,uint _amount) external{
        Shared.advert storage ad = Adverts[advertId];
        require(ad.balance > 0, "insufficient balance");
        require(_amount <= ad.balance,"insufficient funds");
        IBEP20(ad.asset).transferFrom(address(this), buyer,_amount);
        Adverts[advertId].balance -= _amount;
        emit AssetTransferred(advertId, _amount, buyer);
    }

    function getBalance(string memory advertId) external view returns (uint){
        return (Adverts[advertId].balance);
    }
}
